/**
 * Post-lane-commit dirty worktree hygiene (SP-427 / #73).
 * Coverage artifacts regenerated by npm test are ephemeral when not in task file scope.
 */

import { execFileSync } from "node:child_process";
import { loadSpineConfig } from "../config/spine-config-load.mjs";
import { resolveWorktreeSetupHook } from "../config/worktree-setup-hook.mjs";
import { filterPorcelain, gitPorcelain } from "./lane-commit.mjs";
import { gitExec } from "./git-exec.mjs";
import { runWorktreeSetupHook } from "./worktree.mjs";

/**
 * Path segments that identify generated coverage report artifacts.
 * Matches extension/coverage, root coverage dirs, and nested coverage paths.
 */
export const COVERAGE_ARTIFACT_MARKERS = ["/coverage/", "coverage/"];

/**
 * @param {string} filePath
 * @returns {boolean}
 */
export function isCoverageArtifactPath(filePath) {
	if (!filePath || typeof filePath !== "string") return false;
	const normalized = filePath.replace(/\\/g, "/");
	return COVERAGE_ARTIFACT_MARKERS.some(
		(marker) =>
			normalized === marker.slice(0, -1) ||
			normalized.startsWith(marker) ||
			normalized.includes(marker),
	);
}

/**
 * @param {string} filePath
 * @param {string[]} [fileScopePaths]
 * @returns {boolean}
 */
export function isPathInFileScope(filePath, fileScopePaths) {
	if (!filePath || !Array.isArray(fileScopePaths) || fileScopePaths.length === 0) {
		return false;
	}

	const normalizedPath = filePath.replace(/\\/g, "/");
	const scopePrefixes = [];
	for (const rel of fileScopePaths) {
		if (!rel || typeof rel !== "string") continue;
		const normalized = rel.replace(/\\/g, "/");
		scopePrefixes.push(normalized.endsWith("/") ? normalized : `${normalized}/`);
		scopePrefixes.push(normalized);
	}

	return scopePrefixes.some(
		(prefix) => normalizedPath === prefix || normalizedPath.startsWith(prefix),
	);
}

/**
 * @param {string} line
 * @returns {string | null}
 */
function extractPorcelainPath(line) {
	if (!line.trim()) return null;
	let filePath = line.length > 2 && line[2] === " " ? line.slice(3) : line.slice(2);
	filePath = filePath.trim();
	if (!filePath) return null;
	if (filePath.includes(" -> ")) {
		return filePath.split(" -> ").pop()?.trim() ?? null;
	}
	return filePath;
}

/**
 * @param {string} porcelain
 * @returns {string[]}
 */
export function listPorcelainPaths(porcelain) {
	if (!porcelain?.trim()) return [];
	return porcelain
		.split("\n")
		.map((line) => extractPorcelainPath(line))
		.filter((entry) => Boolean(entry));
}

/**
 * @param {string[]} dirtyPaths
 * @param {string[]} [fileScopePaths]
 * @returns {string[]}
 */
export function listOutOfScopeCoveragePaths(dirtyPaths, fileScopePaths) {
	if (!Array.isArray(dirtyPaths) || dirtyPaths.length === 0) return [];
	return dirtyPaths.filter(
		(filePath) => isCoverageArtifactPath(filePath) && !isPathInFileScope(filePath, fileScopePaths),
	);
}

/**
 * @param {string} filePath
 * @returns {string | null}
 */
function coverageRootForPath(filePath) {
	const normalized = filePath.replace(/\\/g, "/");
	const markerIdx = normalized.indexOf("/coverage/");
	if (markerIdx >= 0) {
		return normalized.slice(0, markerIdx + "/coverage".length);
	}
	if (normalized === "coverage" || normalized.startsWith("coverage/")) {
		return "coverage";
	}
	return null;
}

/**
 * @param {string[]} filePaths
 * @param {string[]} [fileScopePaths]
 * @returns {string[]}
 */
export function listOutOfScopeCoverageRoots(filePaths, fileScopePaths) {
	const roots = new Set();
	for (const filePath of filePaths) {
		if (!isCoverageArtifactPath(filePath) || isPathInFileScope(filePath, fileScopePaths)) {
			continue;
		}
		const root = coverageRootForPath(filePath);
		if (root && !isPathInFileScope(root, fileScopePaths)) {
			roots.add(root);
		}
	}
	return [...roots].sort();
}

/**
 * Restore tracked and remove untracked out-of-scope coverage before lane commit.
 *
 * @param {string} worktreePath
 * @param {string[]} [fileScopePaths]
 * @param {{ projectRoot?: string, porcelain?: string }} [options]
 * @returns {{ restored: string[], cleanedRoots: string[] }}
 */
export function sanitizeOutOfScopeCoverageBeforeLaneCommit(
	worktreePath,
	fileScopePaths,
	{ projectRoot, porcelain } = {},
) {
	const identityRoot = projectRoot ?? worktreePath;
	const rawPorcelain = porcelain ?? "";
	const dirtyPaths = listPorcelainPaths(rawPorcelain);
	const { restored } = restoreOutOfScopeCoverageArtifacts(worktreePath, fileScopePaths, {
		projectRoot: identityRoot,
		dirtyPaths,
		porcelain: rawPorcelain,
	});

	const cleanedRoots = listOutOfScopeCoverageRoots(dirtyPaths, fileScopePaths);
	for (const root of cleanedRoots) {
		gitExec(worktreePath, ["clean", "-fd", "--", root], {
			projectRoot: identityRoot,
			throwOnError: false,
		});
	}

	return { restored, cleanedRoots };
}

/**
 * @param {string} porcelain
 * @returns {Set<string>}
 */
function listTrackedPorcelainPaths(porcelain) {
	const tracked = new Set();
	if (!porcelain?.trim()) return tracked;
	for (const line of porcelain.split("\n")) {
		if (!line.trim()) continue;
		const status = line.slice(0, 2);
		if (status === "??" || status === "!!") continue;
		const filePath = extractPorcelainPath(line);
		if (filePath) tracked.add(filePath);
	}
	return tracked;
}

/**
 * Restore tracked coverage artifacts that are outside task file scope.
 *
 * @param {string} worktreePath
 * @param {string[]} [fileScopePaths]
 * @param {{ projectRoot?: string, dirtyPaths?: string[], porcelain?: string }} [options]
 * @returns {{ restored: string[] }}
 */
export function restoreOutOfScopeCoverageArtifacts(
	worktreePath,
	fileScopePaths,
	{ projectRoot, dirtyPaths, porcelain } = {},
) {
	const identityRoot = projectRoot ?? worktreePath;
	const candidates = Array.isArray(dirtyPaths) ? dirtyPaths : [];
	const outOfScope = listOutOfScopeCoveragePaths(candidates, fileScopePaths);
	if (outOfScope.length === 0) {
		return { restored: [] };
	}

	const trackedPaths = listTrackedPorcelainPaths(porcelain ?? "");
	const toRestore = trackedPaths.size > 0
		? outOfScope.filter((filePath) => trackedPaths.has(filePath))
		: outOfScope;
	if (toRestore.length === 0) {
		return { restored: [] };
	}

	gitExec(
		worktreePath,
		["restore", "--source=HEAD", "--worktree", "--", ...toRestore],
		{ projectRoot: identityRoot },
	);
	return { restored: toRestore };
}

/**
 * Drop out-of-scope coverage artifact lines from porcelain after ignore patterns.
 *
 * @param {string} porcelain
 * @param {string[]} [fileScopePaths]
 * @param {string[]} [ignorePatterns]
 * @returns {string}
 */
/**
 * @param {string} line
 * @returns {boolean}
 */
export function isSymlinkDeletionPorcelainLine(line) {
	if (!line?.trim() || line.length < 3) return false;
	const indexStatus = line[0];
	const worktreeStatus = line[1];
	const disallowed = new Set(["M", "A", "R", "C", "U"]);
	if (disallowed.has(indexStatus) || disallowed.has(worktreeStatus)) {
		return false;
	}
	return indexStatus === "D" || worktreeStatus === "D";
}

/**
 * @param {string} line
 * @returns {boolean}
 */
export function isWorktreeDeletionPorcelainLine(line) {
	return isSymlinkDeletionPorcelainLine(line) && line[1] === "D";
}

/**
 * True when every porcelain line is a symlink/hook deletion (` D`, `D `, or `DD`).
 *
 * @param {string} porcelain
 * @returns {boolean}
 */
export function isSymlinkOnlyDriftPorcelain(porcelain) {
	if (!porcelain?.trim()) return false;
	for (const line of porcelain.split("\n")) {
		if (!line.trim()) continue;
		if (!isSymlinkDeletionPorcelainLine(line)) return false;
	}
	return true;
}

/**
 * @param {string} worktreePath
 * @returns {{ batchId: string, laneNumber: number } | null}
 */
export function parseLaneWorktreeIdentity(worktreePath) {
	const normalized = worktreePath.replace(/\\/g, "/");
	const match = normalized.match(/\/\.worktrees\/spine-([^/]+)\/lane-(\d+)\/?$/);
	if (!match) return null;
	return { batchId: match[1], laneNumber: Number(match[2]) };
}

/**
 * @param {string} porcelain
 * @returns {string}
 */
export function filterSetupHookSymlinkDriftPorcelain(porcelain) {
	if (!porcelain?.trim() || !isSymlinkOnlyDriftPorcelain(porcelain)) {
		return porcelain ?? "";
	}
	return "";
}

/**
 * Re-run worktreeSetupHook to recreate hook-managed symlinks after drift.
 *
 * @param {string} worktreePath
 * @param {{ projectRoot: string, config?: object, batchId?: string, laneNumber?: number }} options
 * @returns {{ repaired: boolean, reason?: string }}
 */
export function repairSetupHookSymlinkDrift(worktreePath, { projectRoot, config, batchId, laneNumber }) {
	const effectiveConfig = config ?? loadSpineConfig(projectRoot).config ?? {};
	const hookPath = resolveWorktreeSetupHook(projectRoot, effectiveConfig);
	if (!hookPath) {
		return { repaired: false, reason: "no_hook" };
	}

	const identity = parseLaneWorktreeIdentity(worktreePath);
	const effectiveBatchId = batchId ?? identity?.batchId ?? "unknown";
	const effectiveLaneNumber = laneNumber ?? identity?.laneNumber ?? 1;

	try {
		runWorktreeSetupHook({
			projectRoot,
			worktreePath,
			batchId: effectiveBatchId,
			laneNumber: effectiveLaneNumber,
			config: effectiveConfig,
		});
		return { repaired: true };
	} catch {
		return { repaired: false, reason: "hook_failed" };
	}
}

/**
 * Repair or ignore symlink-only deletions from worktreeSetupHook paths (#87 / SP-429).
 *
 * @param {string} worktreePath
 * @param {string} porcelain
 * @param {{ projectRoot?: string, config?: object, batchId?: string, laneNumber?: number }} [options]
 * @returns {string}
 */
export function resolveSetupHookSymlinkDriftPorcelain(
	worktreePath,
	porcelain,
	{ projectRoot, config, batchId, laneNumber } = {},
) {
	if (!porcelain?.trim() || !isSymlinkOnlyDriftPorcelain(porcelain)) {
		return porcelain ?? "";
	}

	const identityRoot = projectRoot ?? worktreePath;
	const effectiveConfig = config ?? loadSpineConfig(identityRoot).config ?? {};
	if (!resolveWorktreeSetupHook(identityRoot, effectiveConfig)) {
		return porcelain;
	}

	const repair = repairSetupHookSymlinkDrift(worktreePath, {
		projectRoot: identityRoot,
		config: effectiveConfig,
		batchId,
		laneNumber,
	});
	if (repair.repaired) {
		return porcelain;
	}

	return filterSetupHookSymlinkDriftPorcelain(porcelain);
}

/**
 * Split gitignored paths into index-tracked (removable with git rm --cached)
 * and worktree-only (ephemeral artifacts not in the index).
 *
 * @param {string} worktreePath
 * @param {string[]} gitignoredPaths
 * @returns {{ indexTracked: string[], worktreeOnly: string[] }}
 */
export function classifyGitignoredPaths(worktreePath, gitignoredPaths) {
	if (!Array.isArray(gitignoredPaths) || gitignoredPaths.length === 0) {
		return { indexTracked: [], worktreeOnly: [] };
	}

	let indexedOutput = "";
	try {
		indexedOutput = execFileSync(
			"git",
			["ls-files", "--cached", "--", ...gitignoredPaths],
			{
				cwd: worktreePath,
				encoding: "utf-8",
				stdio: ["ignore", "pipe", "pipe"],
			},
		).trim();
	} catch {
		// If ls-files fails, treat all as worktree-only (safe fallback).
		return { indexTracked: [], worktreeOnly: [...gitignoredPaths] };
	}

	const indexedSet = new Set(
		indexedOutput ? indexedOutput.split("\n").map((l) => l.trim()).filter(Boolean) : [],
	);
	const indexTracked = [];
	const worktreeOnly = [];
	for (const p of gitignoredPaths) {
		if (indexedSet.has(p)) {
			indexTracked.push(p);
		} else {
			worktreeOnly.push(p);
		}
	}
	return { indexTracked, worktreeOnly };
}

/**
 * Build a remediation message appropriate for the gitignored path classification.
 *
 * @param {string[]} indexTracked
 * @param {string[]} worktreeOnly
 * @returns {string}
 */
export function formatGitignoredRemediationMessage(indexTracked, worktreeOnly) {
	const allPaths = [...indexTracked, ...worktreeOnly];
	const preview = allPaths.slice(0, 20).join(", ");
	const suffix = allPaths.length > 20 ? "…" : "";
	const prefix = `Lane worktree has gitignored dirty files only (${preview}${suffix})`;

	if (indexTracked.length > 0 && worktreeOnly.length > 0) {
		return (
			`${prefix} — ` +
			`remove index-tracked paths with git rm --cached on the task branch, ` +
			`then git clean -fdX to remove worktree-only artifacts before resume`
		);
	}
	if (indexTracked.length > 0) {
		return (
			`${prefix} — ` +
			`remove from the index with git rm --cached on the task branch before resume`
		);
	}
	return (
		`${prefix} — ` +
		`worktree-only artifacts (not in git index); clean with git clean -fdX before resume`
	);
}

export function filterOutOfScopeCoveragePorcelain(porcelain, fileScopePaths, ignorePatterns = []) {
	const afterIgnore = filterPorcelain(porcelain, ignorePatterns);
	if (!afterIgnore?.trim()) return "";

	const kept = [];
	for (const line of afterIgnore.split("\n")) {
		if (!line.trim()) continue;
		const filePath = extractPorcelainPath(line);
		if (filePath && isCoverageArtifactPath(filePath) && !isPathInFileScope(filePath, fileScopePaths)) {
			continue;
		}
		kept.push(line);
	}
	return kept.length === 0 ? "" : kept.join("\n");
}

/**
 * Resolve porcelain for post-lane-commit validation: restore ephemeral coverage, then filter.
 *
 * @param {string} worktreePath
 * @param {object} [options]
 * @param {string[]} [options.fileScopePaths]
 * @param {string[]} [options.ignorePatterns]
 * @param {string} [options.projectRoot]
 * @param {string} [options.porcelain]
 * @returns {string}
 */
export function resolvePostLaneCommitPorcelain(
	worktreePath,
	{ fileScopePaths, ignorePatterns = [], projectRoot, porcelain, config, batchId, laneNumber } = {},
) {
	const rawPorcelain = typeof porcelain === "string" ? porcelain : "";
	const dirtyPaths = listPorcelainPaths(rawPorcelain);
	const { restored } = restoreOutOfScopeCoverageArtifacts(worktreePath, fileScopePaths, {
		projectRoot,
		dirtyPaths,
		porcelain: rawPorcelain,
	});

	let effectivePorcelain = rawPorcelain;
	if (restored.length > 0) {
		const restoredSet = new Set(restored);
		const kept = [];
		for (const line of rawPorcelain.split("\n")) {
			if (!line.trim()) continue;
			const filePath = extractPorcelainPath(line);
			if (filePath && restoredSet.has(filePath)) continue;
			kept.push(line);
		}
		effectivePorcelain = kept.length === 0 ? "" : kept.join("\n");
	}

	let filtered = filterOutOfScopeCoveragePorcelain(effectivePorcelain, fileScopePaths, ignorePatterns);
	if (!filtered?.trim()) {
		return "";
	}

	if (isSymlinkOnlyDriftPorcelain(filtered)) {
		const identityRoot = projectRoot ?? worktreePath;
		const effectiveConfig = config ?? loadSpineConfig(identityRoot).config ?? {};
		if (resolveWorktreeSetupHook(identityRoot, effectiveConfig)) {
			repairSetupHookSymlinkDrift(worktreePath, {
				projectRoot: identityRoot,
				config: effectiveConfig,
				batchId,
				laneNumber,
			});
			const refreshedPorcelain = gitPorcelain(worktreePath);
			filtered = filterOutOfScopeCoveragePorcelain(
				refreshedPorcelain,
				fileScopePaths,
				ignorePatterns,
			);
			if (!filtered?.trim()) {
				return "";
			}
			if (isSymlinkOnlyDriftPorcelain(filtered)) {
				return "";
			}
		}
	}

	return filtered;
}
